#!/bin/sh
# Mutant read n: a throwaway worktree at the cure head with the cure's generator diff reverted (the curing
# commit's generator change undone, generated files regenerated by xtask), the falsifier read. Never committed.
set -u
n=$1; L=$HOME/.dev-logs/bbnf-lockstep/lw3/orc2-ws-c; W=$HOME/Programming/bbnf-lang-wt/lw3-s5c-mutant
export CARGO_INCREMENTAL=0 CARGO_TARGET_DIR=$HOME/.dev-logs/bbnf-lockstep/lw3/target-bbnf-lang BBNF_CORPUS_DIR=$HOME/.dev-logs/bbnf-lockstep/lw3/s7-spine/corpus
cd $W || exit 2
git checkout -q -- . && python3 -I $L/mutant2.py crates/core/src/backend/rust/emitter/shapes/dispatcher/ref_call.rs || exit 3
echo "head=$(git rev-parse HEAD) mutant=M2 ref-call pre-skip restored files=$(git status --short | wc -l)" > $L/mutant2-r$n.log
cargo clean -p bbnf >> $L/mutant2-r$n.log 2>&1
cargo xtask regen >> $L/mutant2-r$n.log 2>&1; echo "regen rc=$?" >> $L/mutant2-r$n.log
cargo nextest run --cargo-profile ax-iter -p bbnf --test rb_root_whitespace --no-fail-fast >> $L/mutant2-r$n.log 2>&1; echo "rc=$?" >> $L/mutant2-r$n.log
git checkout -q -- .
